using System;
using System.Collections.Generic;

namespace Astrea;

public abstract class ConvertOmenData : OmenData
{
	private Action<List<DiceInstance>> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = InitializeOmenAction(omenInstance);
		ReferenceSingleton<MoonieOmensHandler>.Instance.OnPlayerConvertOmenActions.Add(omenAction);
	}

	protected abstract Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance);

	public override void OmenRemoved()
	{
		ReferenceSingleton<MoonieOmensHandler>.Instance.OnPlayerConvertOmenActions.Remove(omenAction);
	}
}
